const room=window.room={running:false,forced:false,palm:false,rewind:0,calm:0,time:43080};
let composition=0;
new p5(p=>{let texture,parts=[],palette=[],phase=0,t=0,lastTick=-1,frame=0;const glyphs='MW@#%&XQG0O8B$ASZ*+:-.· ',romans=['XII','I','II','III','IV','V','VI','VII','VIII','IX','X','XI'];
function regenerate(){phase=p.random(p.TWO_PI);composition++;palette=Array.from({length:5},()=>[p.random(155,245),p.random(155,245),p.random(175,255)]);parts=[];let layout=p.floor(p.random(4)),count=layout===3?14:p.floor(p.random(5,10));for(let i=0;i<count;i++){let a=i*2.399+phase,r=Math.sqrt(i/count)*.4,x,y,size;if(layout===0){x=.5+Math.cos(a)*r;y=.5+Math.sin(a)*r;size=i===0?.22:p.random(.06,.17)}else if(layout===1){x=.13+.74*i/(count-1);y=.5+Math.sin(i*.9+phase)*.25;size=p.random(.09,.23)}else if(layout===2){x=.5+Math.cos(a)*p.random(.1,.38);y=.5+Math.sin(a)*p.random(.1,.38);size=i<2?.26:p.random(.06,.15)}else{x=p.random(.12,.88);y=p.random(.12,.88);size=p.random(.06,.18)}parts.push({x,y,size,clock:i<3||p.random()>.45,spin:p.random(p.TWO_PI),direction:i%2?1:-1,teeth:p.floor(p.random(18,34)),kind:p.floor(p.random(3)),color:palette[i%5]})}}
function resizeTexture(){let w=320,h=Math.ceil(w*innerHeight/innerWidth);texture=p.createGraphics(w,h);texture.pixelDensity(1);texture.textFont('monospace');texture.textSize(7);texture.textAlign(p.LEFT,p.TOP)}p.setup=()=>{p.createCanvas(innerWidth,innerHeight).parent('art');p.pixelDensity(1);p.frameRate(30);p.noiseDetail(4,.52);resizeTexture();regenerate();addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat){e.preventDefault();room.forced=!room.forced}if(e.key==='1'&&!e.repeat){e.preventDefault();window.toggleCamera?.()}})};
p.windowResized=()=>{p.resizeCanvas(innerWidth,innerHeight);resizeTexture()};
function backgroundLetters(){const g=texture,w=g.width,h=g.height,c=room.calm,speed=room.running?.12:.8,warp=c>.5?1.25:2.1,contrast=c>.5?.65:1.8,cell=7;g.background(250);g.noStroke();for(let y=0;y<h;y+=cell)for(let x=0;x<w;x+=cell){let u=x/w*3.2,v=y/h*3.2,tt=t*speed;let a=p.noise(u*.62+tt*.3,v*.62-tt*.2),b=p.noise(u*.63+7-tt*.22,v*.63+tt*.27);let n=p.noise(u+a*warp,v+b*warp,tt*.16),m=p.noise(u*.46+4+a,v*.46+b,tt*.1);let value=p.constrain(.5+(n-.5)*contrast+(m-.5)*.72,0,1);let ink=1-value,idx=Math.min(glyphs.length-1,Math.floor(ink*(glyphs.length-1))),ch=glyphs[idx],col;if(c<.5){let tone=24+226*value;col=[tone,tone,tone]}else{let k=n*4,lo=Math.floor(k),mix=k-lo,A=palette[lo],B=palette[Math.min(4,lo+1)];col=A.map(v=>p.lerp(236,v,mix*.48+.18))}g.fill(...col);g.rect(x,y,cell,cell);g.fill(c<.5?(value>.58?18:238):(value>.58?65:249));g.text(ch,x,y)}p.image(g,0,0,p.width,p.height)}function gear(r,tooth,rot){p.push();p.rotate(rot);p.beginShape();for(let j=0;j<tooth*4;j++){let a=j*p.TWO_PI/(tooth*4),rr=r*(j%4<2?1:.92);p.vertex(Math.cos(a)*rr,Math.sin(a)*rr)}p.endShape(p.CLOSE);p.circle(0,0,r*1.8);p.circle(0,0,r*.27);for(let j=0;j<7;j++){p.push();p.rotate(j*p.TWO_PI/7);p.line(r*.28,0,r*.82,0);p.pop()}p.pop()}
function clock(q){p.push();p.translate(q.x*p.width,q.y*p.height);let r=q.size*Math.min(p.width,p.height);p.scale(r/190);p.blendMode(p.DIFFERENCE);p.noFill();p.stroke(255,191);p.strokeWeight(1.55);let a=q.spin+room.time*.012*q.direction;if(q.kind===2){gear(170,q.teeth,a);gear(80,Math.max(12,q.teeth-7),-a*1.4);p.pop();return}p.circle(0,0,350);p.circle(0,0,340);p.circle(0,0,310);for(let i=0;i<60;i++){p.push();p.rotate(i*p.TWO_PI/60);p.line(0,-166,0,i%5===0?-149:-159);p.pop()}if(q.kind===0){p.textAlign(p.CENTER,p.CENTER);p.textFont('monospace');p.textSize(23);for(let i=0;i<12;i++){let z=i*p.TWO_PI/12-p.HALF_PI;p.text(String((i+2)%12+1),Math.cos(z)*128,Math.sin(z)*128)}}else{p.textAlign(p.CENTER,p.CENTER);p.textFont('Georgia');p.textSize(24);for(let i=0;i<12;i++){let z=i*p.TWO_PI/12-p.HALF_PI;p.text(romans[i],Math.cos(z)*128,Math.sin(z)*128)}}for(let j=0;j<3;j++){p.push();p.rotate(a*(j%2?1:-1));gear(26-j*5,18+j*4,a);p.pop()}p.push();p.rotate(room.time/3600*p.TWO_PI+q.spin);p.strokeWeight(3);p.line(0,12,0,-100);p.pop();p.push();p.rotate(room.time/43200*p.TWO_PI+q.spin);p.strokeWeight(4);p.line(0,10,0,-65);p.pop();p.circle(0,0,10);p.pop()}
p.draw=()=>{let dt=Math.min(p.deltaTime/1000,.06);room.running=room.forced||room.palm;if(room.running!==p._wasRunning){if(room.running)room.rewind=1.15;p._wasRunning=room.running}room.calm=p.lerp(room.calm,room.running?1:0,.035);if(room.rewind>0){room.rewind-=dt;room.time-=dt*5}else if(room.running)room.time+=dt;t+=dt*(room.running?.18:1.4);if(frame++%2===0)backgroundLetters();else p.image(texture,0,0,p.width,p.height);p.blendMode(p.DIFFERENCE);for(const q of parts)clock(q);p.blendMode(p.BLEND);let tick=Math.floor(room.time);if(room.running&&room.rewind<=0&&tick!==lastTick){lastTick=tick} };
window.regenerateArt=regenerate;
});


